r=Path('research/frontier-44-special-representation-examples-28-six-step-owner-escalation-repairs/cyclotomic_isomorphism');item=Path('items/lem-hecke-intertwiners-produce-local-klr-generators.md');contract=Path('research/frontier-44-special-representation-examples-28-six-step-batch-48.proof-contracts.json');ib=item.read_bytes();cb=contract.read_bytes();(r/'citation-format-item-before.md').write_bytes(ib);(r/'citation-format-contract-before.json').write_bytes(cb);s=ib.decode();old='every quadratic and braid relation (1.14)–(1.15)';new='each of the BK quadratic and braid equations';line=next(x for x in s.splitlines() if x.startswith('1.2 '));assert line.count(old)==1;ns=s.replace(line,line.replace(old,new));d=json.loads(cb);row=next(x for x in d['contracts'][item.stem]['derivations'] if x['id']=='step-1-2');oldclaim=row['claim'];assert oldclaim.count(old)==1;row['claim']=oldclaim.replace(old,new)
cbs=cb.decode();marker='"lem-hecke-intertwiners-produce-local-klr-generators":';st=cbs.index(marker);loc=cbs.index('"id": "step-1-2"',st);cl=cbs.index('"claim": ',loc)+len('"claim": ');parsed,length=json.JSONDecoder().raw_decode(cbs[cl:]);assert parsed==oldclaim;rawclaim=cbs[cl:cl+length];rawold=old if old in rawclaim else old.replace('–',r'\u2013');assert rawclaim.count(rawold)==1;ncbs=cbs[:cl]+rawclaim.replace(rawold,new)+cbs[cl+length:];assert json.loads(ncbs)==d;assert item.read_bytes()==ib and contract.read_bytes()==cb
